INSERT INTO "admin_permissions" ("id","key","description") VALUES ('admin-permission-privacy-read','privacy.read','Veri sahibi taleplerini görüntüler'),('admin-permission-privacy-manage','privacy.manage','Veri sahibi taleplerini ve legal hold kayıtlarını yönetir') ON CONFLICT ("key") DO NOTHING;
INSERT INTO "admin_role_permissions" ("adminRoleId","adminPermissionId") SELECT r."id",p."id" FROM "admin_roles" r CROSS JOIN "admin_permissions" p WHERE r."key" IN ('SUPER_ADMIN','SECURITY') AND p."key" IN ('privacy.read','privacy.manage') ON CONFLICT DO NOTHING;
INSERT INTO "admin_role_permissions" ("adminRoleId","adminPermissionId") SELECT r."id",p."id" FROM "admin_roles" r CROSS JOIN "admin_permissions" p WHERE r."key"='READ_ONLY_AUDITOR' AND p."key"='privacy.read' ON CONFLICT DO NOTHING;
